INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss eine Netzwerkkarte eine IP-Adresse konfiguriert bekommen, um im Netzwerk zu kommunizieren?', 2, '[{"text": "Ja", "correct": true, "because": "IP-Adresse ist für Kommunikation nötig"}, {"text": "Nein", "correct": false, "because": "Ohne IP keine Netzwerkkommunikation"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Switch ohne Konfiguration direkt nach dem Anschließen genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Unmanaged Switches sind plug-and-play"}, {"text": "Nein", "correct": false, "because": "Konfiguration nur bei Managed Switches nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Standard-Gateway-Adresse bei der Konfiguration eines Routers erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Nur für Clients nötig, Router selbst ist oft das Gateway"}, {"text": "Ja", "correct": false, "because": "Router hat eigene Routing-Tabelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen VLANs auf einem Switch konfiguriert werden, um verschiedene Netzwerke zu trennen?', 2, '[{"text": "Ja", "correct": true, "because": "VLANs trennen Netzwerke logisch"}, {"text": "Nein", "correct": false, "because": "Ohne VLANs keine Trennung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Router ohne DHCP-Konfiguration funktionieren?', 2, '[{"text": "Ja", "correct": true, "because": "DHCP ist optional, manuelle IPs möglich"}, {"text": "Nein", "correct": false, "because": "DHCP ist nicht zwingend"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird oft verwendet, um eine Netzwerkkarte mit einer dynamischen IP-Adresse zu konfigurieren?', 2, '[{"text": "DHCP", "correct": true, "because": "Dynamic Host Configuration Protocol vergibt IPs"}, {"text": "SNMP", "correct": false, "because": "Für Überwachung"}, {"text": "FTP", "correct": false, "because": "Für Dateitransfer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einstellung muss auf einem Switch vorgenommen werden, um Netzwerke logisch zu trennen?', 3, '[{"text": "VLAN-Konfiguration", "correct": true, "because": "Virtual LANs trennen Netzwerke"}, {"text": "IP-Adresszuweisung", "correct": false, "because": "Switch arbeitet auf Schicht 2"}, {"text": "DNS-Eintrag", "correct": false, "because": "Für Namensauflösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion muss auf einem Router konfiguriert werden, um den Internetzugang zu ermöglichen?', 2, '[{"text": "NAT", "correct": true, "because": "Network Address Translation verbindet LAN mit WAN"}, {"text": "VLAN", "correct": false, "because": "Für LAN-Trennung"}, {"text": "QoS", "correct": false, "because": "Für Priorisierung, nicht Zugang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle wird typischerweise für die Konfiguration eines Managed Switches verwendet?', 2, '[{"text": "Weboberfläche", "correct": true, "because": "Einfache Verwaltung über Browser"}, {"text": "USB", "correct": false, "because": "Nicht üblich"}, {"text": "Bluetooth", "correct": false, "because": "Nicht für Switches"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse muss auf einer Netzwerkkarte konfiguriert werden, wenn kein DHCP verwendet wird?', 2, '[{"text": "Statische IP-Adresse", "correct": true, "because": "Manuelle Konfiguration nötig"}, {"text": "MAC-Adresse", "correct": false, "because": "Hardwareseitig fest"}, {"text": "Gateway-Adresse allein", "correct": false, "because": "IP nötig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Parameter müssen auf einer Netzwerkkarte konfiguriert werden, um sie funktionsfähig zu machen?', 4, '[{"text": "IP-Adresse", "correct": true, "because": "Für Kommunikation nötig"}, {"text": "Subnetzmaske", "correct": true, "because": "Definiert Netzwerkbereich"}, {"text": "Standard-Gateway", "correct": true, "because": "Für externe Netzwerke"}, {"text": "Bildschirmgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einstellungen können auf einem Managed Switch konfiguriert werden?', 3, '[{"text": "VLANs", "correct": true, "because": "Für Netzwerktrennung"}, {"text": "Portspiegelung", "correct": true, "because": "Für Analysezwecke"}, {"text": "QoS", "correct": true, "because": "Für Datenpriorisierung"}, {"text": "DNS-Server", "correct": false, "because": "Für Router oder Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen müssen auf einem Router konfiguriert werden, um ein funktionierendes Netzwerk zu gewährleisten?', 4, '[{"text": "Routing-Tabelle", "correct": true, "because": "Definiert Datenwege"}, {"text": "NAT", "correct": true, "because": "Für Internetzugang"}, {"text": "Firewall-Regeln", "correct": true, "because": "Für Sicherheit"}, {"text": "MAC-Adressfilter", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle können bei der Konfiguration von Netzwerkgeräten eine Rolle spielen?', 3, '[{"text": "DHCP", "correct": true, "because": "Für IP-Vergabe"}, {"text": "SNMP", "correct": true, "because": "Für Überwachung"}, {"text": "SSH", "correct": true, "because": "Für sichere Konfiguration"}, {"text": "HTTP", "correct": false, "because": "Weniger sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sollten bei der Konfiguration eines Switches berücksichtigt werden?', 3, '[{"text": "Portgeschwindigkeit", "correct": true, "because": "Beeinflusst Leistung"}, {"text": "VLAN-Zuweisung", "correct": true, "because": "Trennt Netzwerke"}, {"text": "Spanning Tree Protocol", "correct": true, "because": "Verhindert Schleifen"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Irrelevant"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine Netzwerkkarte kann statisch oder dynamisch konfiguriert werden. b) Ein Switch benötigt immer eine IP-Adresse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Statisch/dynamisch ja, Switch-IP optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) VLANs müssen auf einem Managed Switch konfiguriert werden, um Netzwerke zu trennen. b) Ein Router kann ohne NAT funktionieren.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "VLANs ja, NAT optional"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) DHCP kann auf einem Router konfiguriert werden. b) Eine Netzwerkkarte benötigt keine Subnetzmaske.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DHCP ja, Subnetzmaske nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Switch kann Portspiegelung für die Analyse konfigurieren. b) Ein Router muss immer WLAN unterstützen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Portspiegelung ja, WLAN optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) SSH bietet eine sichere Methode zur Router-Konfiguration. b) Eine Netzwerkkarte kann ohne Treiber konfiguriert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SSH ja, Treiber nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');